import java.util.Scanner;

public class TextDocumentAnalysis4 {
    private static final class State {
        int maxL = -1;
        int nwi = 0;
        int fp = 0;
        int fw = 0;

        void process(char c) {
            if (c == '(') {
                fp++;
                fw = 0;
            } else if (c == ')') {
                if (fp == 1 && fw != 0) {
                    nwi++;
                }
                fp--;
                fw = 0;
            } else if (c == '_') {
                if (fp == 1 && fw != 0) {
                    nwi++;
                }
                fw = 0;
            } else {
                fw++;
            }
            if (fp == 0) {
                maxL = Math.max(fw, maxL);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        State st = new State();
        for (int i = 0; i < n; i++) {
            st.process(s.charAt(i));
        }
        System.out.println(st.maxL + " " + st.nwi);
    }
}
